(6160104, 908403, 27133, '<td valign="top">This is beautiful.  The birds flying over...I want to be them.  Free and not broken.</td>', 'This is beautiful.  The birds flying over...I want to be them.  Free and not broken.', '2010-09-13 01:16:44.000000', NULL, 1),
(6160105, 909209, 27133, '<td valign="top">I can feel the warmth of the colour in the rainbow.  The cold of the snow melting away around me.</td>', 'I can feel the warmth of the colour in the rainbow.  The cold of the snow melting away around me.', '2010-09-13 01:17:11.000000', NULL, 1),
(6160107, 909000, 27133, '<td valign="top">The fire in the sky is the fire in me when I was trapped inside of me.  The blue is the cold feelings as I came out but couldn''t understand what was going on.</td>', 'The fire in the sky is the fire in me when I was trapped inside of me.  The blue is the cold feelings as I came out but couldn''t understand what was going on.', '2010-09-13 01:18:05.000000', NULL, 1),
