(6165796, 909303, 27133, '<td valign="top">Even through the concrete towers, nature has its way of making itself known and giving everyone hope.</td>', 'Even through the concrete towers, nature has its way of making itself known and giving everyone hope.', '2010-09-19 07:04:22.000000', NULL, 1),
(6165797, 909161, 27133, '<td valign="top">The patterns of the sky always amaze me.  The delicate patterns and blending of colour in a way no one can replicate.</td>', 'The patterns of the sky always amaze me.  The delicate patterns and blending of colour in a way no one can replicate.', '2010-09-19 07:05:08.000000', NULL, 1),
(6165798, 908590, 63812, '<td valign="top">lol...funny</td>', 'lol...funny', '2010-09-19 07:05:30.000000', NULL, 1),
