(6166557, 907442, 27133, '<td valign="top">Tiny droplets of water seem so large against tiny beings...but their colours are so bright and happy.</td>', 'Tiny droplets of water seem so large against tiny beings...but their colours are so bright and happy.', '2010-09-20 00:18:28.000000', NULL, 1),
(6166558, 909250, 27133, '<td valign="top">Wow...so much colour....I love this.  Thankyou.</td>', 'Wow...so much colour....I love this.  Thankyou.', '2010-09-20 00:18:40.000000', NULL, 1),
(6166560, 907544, 27133, '<td valign="top">Hehehehe...he makes me smile.  I have never seen a hat like that...and he seems to not care what others think.  That makes me feel good.</td>', 'Hehehehe...he makes me smile.  I have never seen a hat like that...and he seems to not care what others think.  That makes me feel good.', '2010-09-20 00:19:17.000000', NULL, 1),
(6166567, 908554, 27133, '<td valign="top">I am not sure what this is....but it has so much to see.  A puzzle in an image.  Thankyou.</td>', 'I am not sure what this is....but it has so much to see.  A puzzle in an image.  Thankyou.', '2010-09-20 00:20:11.000000', NULL, 1),
(6166571, 909254, 27133, '<td valign="top">An amazing object of nature that is often overlooked.  You have captured it in a way that makes it just as important as something that ten times its size.</td>', 'An amazing object of nature that is often overlooked.  You have captured it in a way that makes it just as important as something that ten times its size.', '2010-09-20 00:20:50.000000', NULL, 1),
(6166573, 908746, 27133, '<td valign="top">So beautiful and gentle a smile on a girls face.  She seems to be a vry caring girl.  She makes me smile.</td>', 'So beautiful and gentle a smile on a girls face.  She seems to be a vry caring girl.  She makes me smile.', '2010-09-20 00:21:25.000000', NULL, 1),
(6166575, 909054, 27133, '<td valign="top">Wow...I really like this.  The dark foreboding background and yet the flower still stands strong and proud.</td>', 'Wow...I really like this.  The dark foreboding background and yet the flower still stands strong and proud.', '2010-09-20 00:21:53.000000', NULL, 1),
(6166577, 909181, 27133, '<td valign="top">A delicate flower that stands proud, showing its importance to the world.  Thankyou for this.</td>', 'A delicate flower that stands proud, showing its importance to the world.  Thankyou for this.', '2010-09-20 00:22:21.000000', NULL, 1),
(6166578, 909147, 27133, '<td valign="top">This is beautiful.  The strong rays breaking through the endless pattern of clourds.</td>', 'This is beautiful.  The strong rays breaking through the endless pattern of clourds.', '2010-09-20 00:22:45.000000', NULL, 1),
(6166580, 909265, 27133, '<td valign="top">A Monarch butterfly is seen around these parts a lot...but there never cease to amaze me with their beauty.</td>', 'A Monarch butterfly is seen around these parts a lot...but there never cease to amaze me with their beauty.', '2010-09-20 00:23:13.000000', NULL, 1),
(6166582, 909263, 27133, '<td valign="top">Normally seen as something inferior, their colour and boldness always shows that no matter what we are....we can be proud.</td>', 'Normally seen as something inferior, their colour and boldness always shows that no matter what we are....we can be proud.', '2010-09-20 00:23:43.000000', NULL, 1),
(6166583, 909180, 27133, '<td valign="top">So beautiful and cute....with his whole life ahead of him.</td>', 'So beautiful and cute....with his whole life ahead of him.', '2010-09-20 00:24:16.000000', NULL, 1),
(6166584, 909120, 27133, '<td valign="top">Hehehehe...what fun.  To allow yourself to get dirty and just play.  I wish more adults took the time to do this.</td>', 'Hehehehe...what fun.  To allow yourself to get dirty and just play.  I wish more adults took the time to do this.', '2010-09-20 00:24:43.000000', NULL, 1),
