(6167220, 908738, 35357, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by hojop25:</b></div><hr/><i> <table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by paqman:</b></div><hr/><i> What does it mean? </i></td></tr></table> <br/> <br/>Ahahahahahaha </i></td></tr></table> <br/> <br/><a href="//www.youtube.com/watch?v=OQSNhk5ICTI" rel="nofollow" target="_blank">double rainbow</a> <br/> <br/>:-D<br/><br/><i>Message edited by author 2010-09-20 12:21:28.</i></td>', 'Originally posted by hojop25: Originally posted by paqman: What does it mean?   Ahahahahahaha   double rainbow  :-D', '2010-09-20 13:20:59.000000', '2010-09-20 13:21:28.000000', 0),
